package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct {
	TcSensor string
	TcF      decimal.Decimal
}

var WsEofFlag string = "N"
var WsC decimal.Decimal = decimal.NewFromInt(0)
var WsFreeze int64 = 0
var WsCount int64 = 0
var WsFEd string
var WsCEd string

var TempRecVar TempRec

func pow10(n int) decimal.Decimal {
	p := decimal.NewFromInt(1)
	ten := decimal.NewFromInt(10)
	for i := 0; i < n; i++ {
		p = p.Mul(ten)
	}
	return p
}

func pow10Int64(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

// keep low-order digits for a numeric field with integerDigits and scale
func fitToField(d decimal.Decimal, integerDigits int, scale int) decimal.Decimal {
	// modulo 10^(integerDigits+scale) on scaled value, preserving sign
	if d.IsZero() {
		return d.Truncate(int32(scale))
	}
	neg := d.IsNegative()
	abs := d.Abs()
	scaled := abs.Shift(int32(scale)) // abs * 10^scale
	// scaled should be integer (after truncation)
	scaled = scaled.Truncate(0)
	mod := pow10(integerDigits + scale)
	// scaled % mod
	// use integer arithmetic via IntPart if fits (5 digits fits)
	// use decimal Mod
	rem := scaled.Mod(mod)
	// rebuild
	res := rem.Shift(int32(-scale))
	if neg {
		res = res.Neg()
	}
	// ensure scale
	res = res.Truncate(int32(scale))
	return res
}

func formatZPicture(absVal decimal.Decimal, integerDigits int, decimalDigits int, zCount int) string {
	// absVal >=0
	// extract integer and fractional after overflow handling
	// integer overflow already applied via rem, but handle here again for safety
	scaled := absVal.Shift(int32(decimalDigits)).Truncate(0) // integer = value *10^dec
	p10dec := pow10(decimalDigits)
	// integer part
	intPartDec := scaled.Div(p10dec).Truncate(0)
	// fractional part
	fracDec := scaled.Mod(p10dec).Abs()

	// high-order drop for integer part
	if integerDigits > 0 {
		modInt := pow10(integerDigits)
		intPartDec = intPartDec.Mod(modInt)
	}

	intVal := intPartDec.IntPart() // fits
	fracVal := fracDec.IntPart()

	intStr := fmt.Sprintf("%0*d", integerDigits, intVal)
	// apply Z suppression
	// intStr length integerDigits
	seenNonZero := false
	chars := []byte(intStr)
	for i := 0; i < integerDigits; i++ {
		if chars[i] != '0' {
			seenNonZero = true
		}
		// decide suppression for this position
		// suppression only for Z positions (first zCount)
		// if not yet seen non-zero and this char is '0' and i < zCount -> space
		// Need to know if any non-zero prefix before or at i?
		// Use seenNonZero flag that includes current char? For suppress we want to suppress zeros before first non-zero.
		// If current char is non-zero we already set seenNonZero, we keep it.
		// If current char is zero and seenNonZero was false before, we suppress (if i < zCount)
	}
	// second pass to actually produce spaces
	seen := false
	for i := 0; i < integerDigits; i++ {
		if chars[i] != '0' {
			seen = true
		}
		if i < zCount && chars[i] == '0' && !seen {
			// However need to check if there is any non-zero before i
			// since seen is false, it means all up to i are zeros
			chars[i] = ' '
		}
		// note: if seen becomes true due to this position, we already handled, but for '0' seen stays false
	}
	intFormatted := string(chars)
	fracStr := fmt.Sprintf("%0*d", decimalDigits, fracVal)
	if decimalDigits > 0 {
		return intFormatted + "." + fracStr
	}
	return intFormatted
}

func formatZZ9_9(d decimal.Decimal) string {
	abs := d.Abs()
	// for TC-F values, scale 1 fits, integerDigits 3
	// overflow handling: keep low 3 integer digits (handled in format)
	return formatZPicture(abs, 3, 1, 2)
}

func formatSignedZZ9_99(d decimal.Decimal) string {
	sign := ' '
	if d.IsNegative() {
		sign = '-'
	}
	abs := d.Abs()
	body := formatZPicture(abs, 3, 2, 2) // 3+1+2=6
	return string(sign) + body
}

func formatPIC99(v int64) string {
	// low-order 2 digits zero padded
	v = v % 100
	if v < 0 {
		v = -v
	}
	return fmt.Sprintf("%02d", v)
}

// I/O helpers
func readInputLines(path string) []string {
	f, err := os.Open(path)
	if err != nil {
		return nil
	}
	defer f.Close()
	var lines []string
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := scanner.Text()
		// Remove trailing \r if present (CRLF)
		line = strings.TrimSuffix(line, "\r")
		lines = append(lines, line)
	}
	return lines
}

var inputLines []string
var inputIdx int

func MAIN_PARA() {
	// OPEN INPUT TEMP-FILE
	inputLines = readInputLines("input.dat")
	inputIdx = 0
	READ_PARA()
	for !INPUT_DONE() {
		PROCESS_PARA()
	}
	// CLOSE TEMP-FILE (no-op)
	// DISPLAY "READINGS: " WS-COUNT " BELOW ZERO: " WS-FREEZE
	out := "READINGS: " + formatPIC99(WsCount) + " BELOW ZERO: " + formatPIC99(WsFreeze)
	fmt.Println(out)
}

func INPUT_DONE() bool {
	return WsEofFlag == "Y"
}

func READ_PARA() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	// COBOL LINE SEQUENTIAL: pad with spaces on right if shorter than record length 8
	if len(line) < 8 {
		line = line + strings.Repeat(" ", 8-len(line))
	} else if len(line) > 8 {
		line = line[:8]
	}
	// parse
	sensor := line[0:4]
	fStr := line[4:8]
	// fStr digits only
	fStrTrim := strings.TrimSpace(fStr)
	var fVal decimal.Decimal
	if fStrTrim == "" {
		fVal = decimal.NewFromInt(0)
	} else {
		// ensure digits
		// parse as int64
		var iv int64
		_, err := fmt.Sscan(fStrTrim, &iv)
		if err != nil {
			// manual parse digits
			iv = 0
			for _, ch := range fStrTrim {
				if ch >= '0' && ch <= '9' {
					iv = iv*10 + int64(ch-'0')
				}
			}
		}
		fVal = decimal.New(iv, -1) // V9
	}
	TempRecVar.TcSensor = sensor
	TempRecVar.TcF = fVal
}

func PROCESS_PARA() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	// use decimal arithmetic
	tcF := TempRecVar.TcF
	// (tcF -32)*5/9
	diff := tcF.Sub(decimal.NewFromInt(32))
	mul := diff.Mul(decimal.NewFromInt(5))
	div := mul.Div(decimal.NewFromInt(9))
	rounded := div.Round(2) // half away (shopspring does half up)
	// store into S9(3)V99 with overflow truncation
	fitted := fitToField(rounded, 3, 2)
	WsC = fitted

	if WsC.IsNegative() {
		// ADD 1 TO WS-FREEZE with overflow (PIC 99)
		WsFreeze = (WsFreeze + 1) % 100
	}
	WsCount = (WsCount + 1) % 100

	WsFEd = formatZZ9_9(tcF)
	WsCEd = formatSignedZZ9_99(WsC)

	// DISPLAY TC-SENSOR " " WS-F-ED "F " WS-C-ED "C"
	// TC-SENSOR is X(4) exactly 4 chars
	fmt.Println(TempRecVar.TcSensor + " " + WsFEd + "F " + WsCEd + "C")

	READ_PARA()
}

func main() {
	MAIN_PARA()
}

